import test from 'node:test';import assert from 'node:assert/strict';import{buildSyntheticWholePackageFixture}from'./whole-package-synthetic.ts';
const target={protocol:'STANDARD_IMPORT_SQL_V1' as const,system_identifier:'123456789',database_oid:'42',database_name:'synthetic_offline_v2',catalog_sha256:'a'.repeat(64)};const secret='naijue:scrypt:1:32768:8:1:'+'c'.repeat(32)+':'+'d'.repeat(128);
test('synthetic only program retains original phases and creates a bounded failure injection',()=>{const x=buildSyntheticWholePackageFixture(target,secret);assert.equal(x.packageKind,'SYNTHETIC');assert.equal(x.program.initialize.payload.document_batch_id,x.documentBatchId);assert.ok(x.program.steps.some(s=>s.method==='masterChunk'));assert.ok(x.program.steps.some(s=>s.method==='publish'&&s.request.payload.phase==='BASELINE'));assert.ok(x.program.steps.some(s=>s.method==='publish'&&s.request.payload.phase==='DOCUMENTS'));assert.ok(x.constraintFailureAt>=0);assert.equal(x.constraintFailureStep.method,'masterChunk');assert.ok(x.sealedAppendAfter>=0);const sealed=x.program.steps[x.sealedAppendAfter]!;assert.equal(x.sealedAppendStep.method,'documentChunk');assert.notEqual(x.sealedAppendStep.request.operation_id,sealed.request.operation_id);assert.equal(x.sealedAppendStep.request.payload.expected_sequence,Number(sealed.request.payload.expected_sequence)+1);assert.deepEqual(x.sealedAppendStep.request.payload.documents,[]);assert.equal((x.sealedAppendStep.request.payload.rows as unknown[]).length,1);assert.ok(!JSON.stringify(x.program).includes(secret));assert.throws(()=>buildSyntheticWholePackageFixture(target,'not-scrypt'));});
test('synthetic snapshot returns hashes and counts, never row bodies',async()=>{const {snapshotSyntheticDatabase}=await import('./whole-package-synthetic.ts');const names=['product','sku','sku_barcode','import_batch','import_record','operation_receipt','audit_change',...Array.from({length:28},(_,i)=>`table_${i}`)];const observer={async query(sql:string){if(sql.includes("relkind IN ('r','p')"))return{rows:names.map(relname=>({relname}))};if(sql.includes("relkind='S'"))return{rows:[{relname:'synthetic_seq'}]};if(sql.includes('last_value'))return{rows:[{value:'1',called:false}]};assert.match(sql,/sha256/);return{rows:[{count:'0',sha256:'a'.repeat(64)}]}}};const result=await snapshotSyntheticDatabase(observer);assert.equal(Object.keys(result.tables).length,35);assert.deepEqual(result.sequences.synthetic_seq,{value:'1',called:false});assert.ok(!JSON.stringify(result).includes('password'));await assert.rejects(snapshotSyntheticDatabase({async query(){return{rows:[]}}}),/SYNTHETIC_SCHEMA_SCOPE_INVALID/)});
for(const variant of ['large-document','departure-null','departure-date'] as const)test('real PG fixture passes package compiler: '+variant,()=>{const f=buildSyntheticWholePackageFixture(target,secret,variant);const rows=f.program.steps.flatMap(s=>(s.request.payload.rows??[]) as {entity_type:string;fields:Record<string,unknown>}[]);if(variant==='large-document'){assert.equal(rows.filter(r=>r.entity_type==='SALES_LINE').length,501);assert.ok(f.program.steps.filter(s=>s.method==='documentChunk'&&s.request.payload.mode==='CHUNK').length>=2);}else{const staff=rows.filter(r=>r.entity_type==='STAFF');assert.ok(staff.length>0);assert.ok(staff.every(r=>r.fields.departure_date===(variant==='departure-null'?null:'2024-02-29')));}});
test('zero/unknown PG fixture explicitly declares a zero and leaves a third warehouse key uncovered',()=>{
 const f=buildSyntheticWholePackageFixture(target,secret,'zero-unknown');assert.equal(f.syntheticWarehouseRows.length,3);
 const rows=f.program.steps.filter(s=>s.method==='baselineKeys').flatMap(s=>(s.request.payload.rows??[]) as {fields:Record<string,unknown>;ledger_entry_id:string|null}[]);
 assert.deepEqual(rows.map(r=>String(r.fields.quantity)).sort(),['0','100']);
 const ids=new Set(rows.map(r=>r.fields.warehouse_id));assert.equal(ids.has(f.syntheticWarehouseRows[2]!.id),false);
 assert.equal(rows.find(r=>r.fields.quantity==='0')?.ledger_entry_id,null);
});
